0\\u0435\\u0442 embedding-\\u0441\\u043b\\u043e\\u0439); \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430, \\u0447\\u0442\\u043e \\u043d\\u0438 \\u043e\\u0434\\u0438\\u043d \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440 \\u0438\\u0437 train \\u043d\\u0435 \\u043f\\u043e\\u043f\\u0430\\u0434\\u0430\\u0435\\u0442 \\u0432 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u044b; \\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u044b\\u0439 \\u043f\\u043e\\u0440\\u044f\\u0434\\u043e\\u043a/ID \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432 \\u0434\\u043b\\u044f paired-\\u0442\\u0435\\u0441\\u0442\\u043e\\u0432.\\n\\u0412\\u0430\\u0440\\u0438\\u0430\\u0442\\u0438\\u0432\\u043d\\u043e\\u0441\\u0442\\u044c \\u0438 \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0430 (\\u0434\\u043b\\u044f \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 \\u0431\\u0435\\u0437 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f):\\n- greedy/likelihood \\u044d\\u0432\\u0430\\u043b \\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d \\u043f\\u043e \\u0441\\u0443\\u0442\\u0438; \\u0435\\u0434\\u0438\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a \\u0448\\u0443\\u043c\\u0430 \\u2014 \\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u0430\\u044f \\u043d\\u0435\\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c \\u2192 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d 1 \\u0440\\u0430\\u0437, \\u043d\\u043e \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c seed \\u0432\\u0435\\u0437\\u0434\\u0435.\\n- \\u0420\\u0430\\u0437\\u043c\\u0435\\u0440: \\u043f\\u043e\\u043b\\u043d\\u044b\\u0439 dev/test-CS \\u043d\\u0430\\u0431\\u043e\\u0440(\\u044b) (\\u0434\\u043b\\u044f CSQA \\u2014 1221 dev-\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u0