acher), base-\\u0432\\u0435\\u0440\\u0441\\u0438\\u044f, Llama-2 tokenizer;\\n- \\u00aboutperform\\u00bb = \\u0432\\u044b\\u0448\\u0435 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 CS-accuracy, \\u0430 \\u043d\\u0435 \\u043f\\u043e \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0437\\u0430\\u0434\\u0430\\u0447\\u043a\\u0435;\\n- \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u00abFuseLLM vs Llama-2-7B\\u00bb, \\u0430 \\u043d\\u0435 vs \\u0447\\u0430\\u0442-\\u0432\\u0435\\u0440\\u0441\\u0438\\u0438;\\n- \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d-only: \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0435 \\u043f\\u043b\\u0430\\u043d\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f, \\u0432\\u0435\\u0441\\u0430/\\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0431\\u0443\\u0434\\u0443\\u0442 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044bresearcher'\\u0443 \\u0432\\u043d\\u0435 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u044b.\\n\\u041e\\u0442\\u043a\\u0440\\u044b\\u0442\\u044b\\u0435 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u044b (\\u043d\\u0443\\u0436\\u0435\\u043d clarification, \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 6):\\n1) \\u0422\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0441\\u043e\\u0441\\u0442\\u0430\\u0432 CS-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0430 \\u0438 setting (zero vs few-shot) \\u043f\\u043e setup_2/setup_9: \\u043e\\u0434\\u043d\\u0430 CommonSenseQA \\u0438\\u043b\\u0438 \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 (\\u043a\\u0430\\u043a\\u0438\\u0435 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438, \\u043a\\u0430\\u043a\\u043e\\u0439 \\u0441\\u043f\\u043b\\u0438\\u0442, \\u043a\\u0430\\u043a\\u0430\\u044f \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430-\\u043a\\u043e\\u043b\\u043e\\u043d\\u043a\\u0430)?\\n2) \\u041a\\u0430\\u043a\\u043e\\u0439 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0447\\u0435\\u043a\\u043f\\u043e\\u0439\\u043d\\u0442 FuseLLM \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0443\\u0435\\u0442\\u0441\\u044f (repo/\\u0438\\u043c\\u044f), base \\u0438\\u043b\\u0438 instruction; \\u043a\\u0430\\u043a\\u0438\\u0435 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u044b; \\u043a\\u0430\\u043a\\u043e\\u0439 eval-harness \\u0432 \\u0438\\u0445 \\u0440\\u0435\\u043f\\u043e?\\n3) \\u0424\\u043e\\u0440\\u043c\\u0430\\u0442 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u043e\\u0432: \\u0438\\u0445 \\u0441\\u043e\\u0431\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0441\\u043a\\u0440\\u0438\\u043f\\u0442 \\u0438\\u043b\\u0438 Llama-2 eval / lm-eval-harness? \\u041a\\u0430\\u043a \\u043f\\u0430\\u0440\\u0441\\u0438\\u0442\\u0441\\u044f \\u043e\\u0442\\u0432\\u0435\\u0442?\\n4) \\u0411\\u0443\\u0434\\u0443\\u0442 \\u043b\\u0438 \\u0432\\u0435\\u0441\\u0430/\\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b \\u043f\\u0440\\u0435\\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u044b \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u043e (Llama-2 \\u2014 gated), \\u0438\\u043b\\u0438 \\u043e\\u0441\\u0442\\u0430\\u0451\\u043c\\u0441\\u044f \\u0441\\u0442\\u0440\\u043e\\u0433\\u043e design-only?\\n5) \\u041a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u0443\\u0441\\u043f\\u0435\\u0445\\u0430: \\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 \\u0431\\u0430\\u043b\\u043b CS \\u0438\\u043b\\u0438 \\u043f\\u043e-\\u0437\\u0430\\u0434\\u0430\\u0447\\u043d\\u043e; \\u043d\\u0443\\u0436\\u0435\\u043d \\u043b\\u0438 13B-\\u0440\\u0435\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441?\\n6) \\u0411\\u044e\\u0434\\u0436\\u0435\\u0442 \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u0438\\u0439, \\u0435\\u0441\\u043b\\u0438 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0432\\u0441\\u0451-\\u0442\\u0430\\u043a\\u0438 \\u043f\\u043b\\u0430\\u043d\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f (CPU-only inference \\u0434\\u043b\\u044f 7B/13B \\u0437\\u0434\\u0435\\u0441\\u044c \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u043d\\u0435\\u043f\\u0440\\u0438\\u0433\\u043e\\u0434\\u0435\\u043d).\\n\\u041d\\u0435 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c\\u043e \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435: \\u0442\\u0435\\u043a\\u0441\\u0442 FuseLLM-\\u0441\\u0442\\u0430\\u0442\\u044c\\u0438/\\u0440\\u0435\\u043f\\u043e \\u0438 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 CS; \\u043d\\u0430\\u043b\\u0438\\u0447\\u0438\\u0435/\\u0438\\u043c\\u0435\\u043d\\u0430 HF-\\u0447\\u0435\\u043a\\u043f\\u043e\\u0439\\u043d\\u0442\\u043e\\u0432; \\u043f\\u043e\\u0432\\u0435\\u0434\\u0435\\u043d\\u0438\\u0435 harness; \\u043b\\u044e\\u0431\\u044b\\u0435 \\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b (\\u0438\\u0445 \\u043d\\u0435\\u0442 \\u0438 \\u043d\\u0435 \\u0431\\u0443\\u0434\\u0435\\u0442 \\u2014 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043b\\u043e\\u0441\\u044c).\", \"evidence\": \"\\u0421\\u0440\\u0435\\u0434\\u043e\\u0432\\u044b\\u0435 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438 (\\u0432\\u0441\\u0435 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u044b): (1) ls -laR /workspace + find: \\u0435\\u0434\\u0438\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0444\\u0430\\u0439\\u043b \\u2014 task.json (407 \\u0431\\u0430\\u0439\\u0442) \\u0441 \\u0442\\u0435\\u043a\\u0441\\u0442\\u043e\\u043c \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u0430 \\u0438 \\u0441\\u0442\\u0440\\u043e\\u043a\\u043e\\u0439 \\\"Design-only task; repositories and compute are not required\\\"; \\u043d\\u0438 \\u0440\\u0435\\u043f\\u043e, \\u043d\\u0438 \\u0441\\u0442\\u0430\\u0442\\u0435\\u0439, \\u043d\\u0438 \\u0441\\