lf-distillation, \\u043a\\u043e\\u043b\\u043e\\u043d\\u043a\\u0430 CS \\u0432 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430\\u0445) \\u043f\\u043e\\u043c\\u0435\\u0447\\u0435\\u043d\\u043e \\u043a\\u0430\\u043a \\u043d\\u0435\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u0430\\u044f \\u043f\\u0430\\u043c\\u044f\\u0442\\u044c, \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435 \\u043d\\u0435 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043e.\", \"assumptions\": [\"FuseLLM checkpoint \\u2014 7B fused \\u0438\\u0437 Llama-2-7B (student) \\u0438 Llama-2-13B (teacher), base-\\u0432\\u0435\\u0440\\u0441\\u0438\\u0438, \\u0441 Llama-2 \\u0442\\u043e\\u043a\\u0435\\u043d\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u043e\\u043c (\\u043f\\u043e \\u043d\\u0435\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 \\u043e \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435)\", \"CS-\\u0441\\u043f\\u043b\\u0438\\u0442 \\u0432 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0435 \\u2014 \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 \\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u0438\\u0445 common-sense \\u0437\\u0430\\u0434\\u0430\\u0447; \\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0441\\u043e\\u0441\\u0442\\u0430\\u0432 \\u043d\\u0435 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435 \\u0438 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 clarification\", \"\\u041f\\u043e\\u0434 'Llama-2' \\u0432 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0438 \\u0438\\u043c\\u0435\\u0435\\u0442\\u0441\\u044f \\u0432 \\u0432\\u0438\\u0434\\u0443 \\u0431\\u0430\\u0437\\u043e\\u0432\\u0430\\u044f (\\u043d\\u0435 chat) Llama-2 \\u0442\\u043e\\u0433\\u043e \\u0436\\u0435 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u0430, \\u0447\\u0442\\u043e student\", \"\\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u2014 accuracy \\u0441 likelihood-\\u043e\\u0446\\u0435\\u043d\\u043a\\u043e\\u0439 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u043e\\u0432, \\u043e\\u0434\\u0438\\u043d \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0434\\u043b\\u044f \\u043e\\u0431\\u0435\\u0438\\u0445 \\u0441\\u0442\\u043e\\u0440\\u043e\\u043d; 'outperform' = \\u0432\\u044b\\u0448\\u0435 \\u043f\\u043e \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442\\u0443 CS\", \"\\u0422\\u0430\\u0441\\u043a design-only: \\u043d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0435 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0438 \\u043d\\u0435 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u044f\\u044e\\u0442\\u0441\\u044f, \\u0432\\u0435\\u0441\\u0430/\\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435 \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044b \\u0438 \\u043d\\u0435 \\u0442\\u0440\\u0435\\u0431\\u0443\\u044e\\u0442\\u0441\\u044f\"], \"uncertainties\": [\"\\u0421\\u043e\\u0441\\u0442\\u0430\\u0432 CS-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0430 (\\u043e\\u0434\\u043d\\u0430 CommonSenseQA \\u0438\\u043b\\u0438 \\u043d\\u0430\\u0431\\u043e\\u0440 PIQA/WinoGrande/HellaSwag/ARC/SIQA/OBQA/SciQ) \\u0438 zero- vs few-shot \\u2014 \\u041d\\u0415 \\u041e\\u041f\\u0420\\u0415\\u0414\\u0415\\u041b\\u0415\\u041d\\u041e, \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0435\\u043d \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u043e\", \"\\u041a\\u0430\\u043a\\u043e\\u0439 harness \\u0438 \\u043a\\u0430\\u043a\\u0438\\u0435 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u044b \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u044e\\u0442 \\u0430\\u0432\\u0442\\u043e\\u0440\\u044b FuseLLM; \\u043a\\u0430\\u043a \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u043f\\u0430\\u0440\\u0441\\u0438\\u0442\\u0441\\u044f \\u043e\\u0442\\u0432\\u0435\\u0442\", \"\\u041f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0443\\u044e\\u0442\\u0441\\u044f \\u043b\\u0438 \\u0447\\u0435\\u043a\\u043f\\u043e\\u0439\\u043d\\u0442\\u044b FuseLLM \\u0438 \\u0432 \\u043a\\u0430\\u043a\\u043e\\u043c \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u0435 (base/instruct, \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u044b); Llama-2 \\u0432\\u0435\\u0441\\u0430 gated \\u2014 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 \\u0438\\u0445 \\u0444\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u043e\\u0441\\u0442\\u0438\", \"\\u041e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 'outperform' (\\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 vs \\u043f\\u043e-\\u0437\\u0430\\u0434\\u0430\\u0447\\u043d\\u043e) \\u0438 \\u043d\\u0443\\u0436\\u0435\\u043d \\u043b\\u0438 \\u0440\\u0435\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 Llama-2-13B\", \"\\u0415\\u0441\\u043b\\u0438 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435: CPU-only \\u0431\\u0435\\u0437 \\u0441\\u0435\\u0442\\u0438 \\u0434\\u0435\\u043b\\u0430\\u0435\\u0442 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u0437\\u0434\\u0435\\u0441\\u044c \\u043d\\u0435\\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u043d\\u044b\\u043c \\u2014 \\u043d\\u0443\\u0436\\u043d\\u0430 \\u0432\\u043d\\u0435\\u0448\\u043d\\u044f\\u044f \\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430 \\u0432\\u0435\\u0441\\u043e\\u0432/\\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0438\\u043b\\u0438 \\u043e\\u0442\\u043a\\u0430\\u0437 \\u043e\\u0442 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0