434\\u043b\\u0438\\u043d\\u044b \\u0438 \\u043f\\u043e\\u043b\\u0438\\u0442\\u0438\\u043a\\u0430 \\u0443\\u0441\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f; dtype=fp16; \\u0443\\u0441\\u0442\\u0440\\u043e\\u0439\\u0441\\u0442\\u0432\\u043e/\\u0431\\u0438\\u0431\\u043b\\u0438\\u043e\\u0442\\u0435\\u043a\\u0438/\\u0432\\u0435\\u0440\\u0441\\u0438\\u0438; \\u043f\\u043e\\u0440\\u044f\\u0434\\u043e\\u043a \\u0438 ID \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432; \\u043f\\u0430\\u0440\\u0441\\u0435\\u0440; RNG seed (\\u0437\\u0430\\u0440\\u0430\\u043d\\u0435\\u0435, \\u0434\\u043b\\u044f bootstrap). \\u041d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0445 model-specific \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u043e\\u0432, \\u043d\\u0438\\u043a\\u0430\\u043a\\u043e\\u0433\\u043e early-stop \\u043f\\u043e \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u0430\\u043c, \\u043d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0445 \\u043f\\u043e\\u0434\\u0441\\u0435\\u0442\\u0435\\u0439, \\u0432\\u044b\\u0431\\u0440\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043f\\u043e\\u0441\\u043b\\u0435 \\u0432\\u0437\\u0433\\u043b\\u044f\\u0434\\u0430 \\u043d\\u0430 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0435.\\n\\n=== 3. \\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b zero-shot \\u0438 \\u0441\\u043a\\u0440\\u0438\\u043d\\u0438\\u043d\\u0433 \\u043e\\u0442\\u0432\\u0435\\u0442\\u043e\\u0432 ===\\n\\u041c\\u0435\\u0442\\u043e\\u0434\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0441\\u0442\\u043e\\u0440\\u043e\\u043d\\u044b \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435\\u0440\\u0430 (\\u041d\\u0415 \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 \\u043e \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0435 \\u0430\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432 FuseLLM): \\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0439 lm-eval-harness-\\u0441\\u0442\\u0438\\u043b\\u044c, \\u043e\\u0434\\u0438\\u043d \\u043e\\u0431\\u0449\\u0438\\u0439 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433 \\u043d\\u0430 \\u0432\\u0441\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438.\\n- \\u0428\\u0430\\u0431\\u043b\\u043e\\u043d: \\u00ab[\\u0437\\u0430\\u0434\\u0430\\u0447\\u0430-specific instruction] {context/question}\\\\n(A)..(E)\\\\nAnswer:\\u00bb \\u2014 \\u043e\\u0434\\u0438\\u043d \\u0448\\u0430\\u0431\\u043b\\u043e\\u043d \\u043d\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0443, 0 \\u0434\\u0435\\u043c\\u043e-\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432.\\n- \\u0421\\u043a\\u043e\\u0440\\u0438\\u043d\\u0433: likelihood, \\u043d\\u0435 \\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0446\\u0438\\u044f. \\u0414\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u0430 scoring logP(\\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 | \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442) \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043d\\u0438\\u043c-\\u0442\\u043e\\u043a\\u0435\\u043d \\u0441\\u0443\\u043c\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435\\u043c log-likelihood \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432 \\u043f\\u0440\\u043e\\u0434\\u043e\\u043b\\u0436\\u0435\\u043d\\u0438\\u044f; \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u043a\\u0430 \\u043f\\u043e \\u0434\\u043b\\u0438\\u043d\\u0435 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u0430 (acc-norm style, \\u0432\\u044b\\u0431\\u043e\\u0440 \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u043a\\u0438 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0434\\u043e \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432 \\u0438 \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432); \\u0432\\u044b\\u0431\\u043e\\u0440 argmax. \\u0411\\u0443\\u043a\\u0432\\u0435\\u043d\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0442\\u043a\\u0438 (\\u00abA\\u00bb) \\u043a\\u0430\\u043a \\u043f\\u0440\\u043e\\u0434\\u043e\\u043b\\u0436\\u0435\\u043d\\u0438\\u044f \\u041d\\u0415 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u044e\\u0442\\u0441\\u044f \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u0442\\u0435\\u043a\\u0441\\u0442 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u0430 (\\u0437\\u0430\\u0449\\u0438\\u0442\\u0430 \\u043e\\u0442 length/letter bias), \\u043f\\u0440\\u0438 \\u044d\\u0442\\u043e\\u043c \\u0434\\u043b\\u0438\\u043d\\u0430 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u0430 \\u0443\\u0447\\u0442\\u0435\\u043d\\u0430 \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u043a\\u043e\\u0439.\\n- \\u0414\\u0435\\u043a\\u043e\\u0434\\u0438\\u043d\\u0433\\u0430 \\u043d\\u0435\\u0442 (greedy \\u043d\\u0435 \\u043d\\u0443\\u0436\\u0435\\u043d; temperature=0 \\u0442\\u0440\\u0438\\u0432\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f). \\u0412\\u0441\\u0435 pass@k/\\u0441\\u044d\\u043c\\u043f\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u044b.\\n-sanity-\\u043f\\u0430\\u0440\\u0441\\u0435\\u0440 \\u0434\\u043b\\u044foptional \\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u043e\\u0439 \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 (\\u0435\\u0441\\u043b\\u0438 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442): regex \\u043f\\u0435\\u0440\\u0432\\u043e\\u0439 \\u043b\\u0438\\u0442\\u0435\\u0440\\u044b \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u0430; \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u043d\\u0435 \\u0432\\u0445\\u043e\\u0434\\u0438\\u0442.\\n\\n=== 4. Controls (\\u043f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u0441\\u043f\\u0438\\u0441\\u043e\\u043a) ===\\nC1. \\u0418\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u044b\\u0439 harness, \\u0432\\u0435\\u0440\\u0441\\u0438\\u044f \\u0438 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0430 \\u043d\\u0430 \\u043e\\u0431\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 (\\u043e\\u0434\\u0438\\u043d git-commit harness, \\u043b\\u043e\\u0433 \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438).\\nC2. \\u0418\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d \\u0438 0-shot \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439.\\nC3. \\u0418\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u0430\\u044f \\u043f\\u043e\\u043b\\u0438\\u0442\\u0438\\u043a\\u0430 \\u0443\\u0441\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f \\u0438 max_seq_len (4096; \\u043f\\u0440\\u0438 \\u043f\\u0435\\u0440\\u0435\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0438 \\u2014 \\u0443\\u0441\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 left \\u0441 \\u043b\\u043e\\u0433\\u043e\\u043c \\u0447\\u0438\\u0441\\u043b\\u0430 \\u0443\\u0441\\u0435\\u0447\\u0451\\u043d\\u043d\\u044b\\u0445 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432 \\u043d\\u0430 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c; \\u0434\\u043e\\u043b\\u044f \\u0443\\u0441\\u0435\\u0447\\u0435\\u043d\\u0438\\u0439 \\u043d\\u0435 \\u0434\\u043e\\u043b\\u0436\\u043d\\u0430 \\u0440\\u0430\\u0437\\u043b\\u0438\\u0447\\u0430\\u0442\\u044c\\u0441\\u044f \\u043c\\u0435\\u0436\\u0434\\u0443 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044f\\u043c\\u0438).\\nC4. \\u0418\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u044b\\u0439 \\u0442\\u043e\\u043a\\u0435\\u043d\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440: \\u0447\\u0435\\u043a-\\u0444\\u0430\\u043a\\u0442 \\u2014 vocab, special tokens, tokenizer config FuseLLM == Llama-2-7B byte-\\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u044b (\\u043a\\u0440\\u0438\\u0442\\u0438\\u0447\\u043d\\u043e, \\u0442.\\u043a. fusion \\u0442\\u0440\\u043e\\u0433\\u0430\\u0435\\u0442 embedding-\\u0441\\u043b\\u043e\\u0439; \\u0440\\u0430\\u0441\\u0441\\u0438\\u043d\\u0445\\u0440\\u043e\\u043d vocab = \\u0432\\u0430\\u043b\\u0438\\u0434\\u043d\\u043e\\u0441\\u0442\\u043d\\u0430\\u044f \\u043e\\u0448\\u0438\\u0431\\u043a\\u0430, \\u043e\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0430).\\nC5. \\u041e\\u0434\\u043d\\u0430 dtype (fp16), \\u043e\\u0434\\u043d\\u043e \\u0443\\u0441\\u0442\\u0440\\u043e\\u0439\\u0441\\u0442\\u0432\\u043e-\\u043a\\u043b\\u0430\\u0441\\u0441, \\u043e\\u0434\\u0438\\u043d batch-\\u0440\\u0435\\u0436\\u0438\\u043c; batch \\u043d\\u0435 \\u0432\\u043b\\u0438\\u044f\\u0435\\u0442 \\u043d\\u0430 likelihood (\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u043d\\u0430 \\u043f\\u043e\\u0434\\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0435 100 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432: batch=1 vs batch=8 \\u2192 \\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u044b\\u0435 \\u0441\\u043a\\u043e\\u0440\\u044b \\u0441 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e 1e-4).\\nC6. Leak-check train-vs-prompt: \\u043f\\u0435\\u0440\\u0435\\u0441\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0432\\u0445\\u043e\\u0434\\u043d\\u044b\\u0445 \\u0441\\u0442\\u0440\\u043e\\u043a eval-\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432 \\u0441 train-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0430\\u043c\\u0438 \\u044d\\u0442\\u0438\\u0445 \\u0436\\u0435 \\u0437\\u0430\\u0434\\u0430\\u0447 (exact + near-dup hashing) \\u2014 \\u043f\\u0443\\u0441\\u0442\\u043e; 0-shot \\u21d2 \\u0443\\u0447\\u0435\\u0431\\u043d\\u044b\\u0445 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432 \\u0432 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u0435 \\u043d\\u0435\\u0442 \\u043f\\u043e \\u043f\\u043e\\u0441\\u0442\\u0440\\u043e\\u0435\\u043d\\u0438\\u044e.\\nC7. \\u0418\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c ID-\\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0430: \\u043e\\u0431\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u044e\\u0442 \\u043e\\u0434\\u0438\\u043d \\u0438 \\u0442\\u043e\\u0442 \\u0436\\u0435 manifest (task_id, item_id) \\u0432 \\u043e\\u0434\\u043d\\u043e\\u043c \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0435; paired-\\u0442\\u0435\\u0441\\u0442 \\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e item_id, \\u043d\\u0435 \\u043f\\u043e \\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u0438.\\nC8. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438: \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u00ab\\u0448\\u0430\\u043c-\\u043c\\u043e\\u0434\\u0435\\u043b\\u0438\\u00bb (Llama-2-7B \\u0434\\u0432\\u0430\\u0436\\u0434\\u044b, \\u0434\\u0432\\u0430 \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u044b\\u0445 \\u0440\\u0430\\u043d\\u0430) \\u2014 \\u0440\\u0430\\u0441\\u0445\\u043e\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043e\\u0442 \\u0447\\u0438\\u0441\\u043b\\u043e\\u0432\\u043e\\u0439 \\u043d\\u0435\\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 (\\u0441\\u043c. \\u00a75), \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u043e ~0; \\u0435\\u0441\\u043b\\u0438 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0435 \\u2014 \\u043f\\u0440\\u043e\\u0431\\u043b\\u0435\\u043c\\u0430 harness.\\nC9. \\u0424\\u0438\\u043a\\u0441\\u0430\\u0446\\u0438\\u044f \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u043e\\u0432 \\u0434\\u043e \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430: \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0438, \\u043c\\u0430\\u043d\\u0438\\u0444\\u0435\\u0441\\u0442\\u044b, \\u0445\\u044d\\u0448\\u0438 \\u0432\\u0435\\u0441\\u043e\\u0432 \\u0438 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 (SHA256) \\u043b\\u043e\\u0433\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0434\\u043e \\u043f\\u0435\\u0440\\u0432\\u043e\\u0433\\u043e \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430.\\n\\n=== 5. \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437: primary/secondary, power/MDE, \\u043d\\u0435\\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c ===\\n- Primary/secondary \\u043a\\u0430\\u043a \\u0432 \\u00a71 (McNemar \\u043d\\u0430 paired correctness \\u043f\\u043e \\u043e\\u0431\\u044a\\u0435\\u0434\\u0438\\u043d\\u0451\\u043d\\u043d\\u044b\\u043c \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c + bootstrap CI \\u043d\\u0430 macro-\\u0394; Holm \\u0434\\u043b\\u044f \\u043f\\u043e-\\u0437\\u0430\\u0434\\u0430\\u0447\\u043d\\u044b\\u0445).\\n- MDE (\\u0430\\u043d\\u0430\\u043b\\u0438\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0440\\u0430\\u0441\\u0447\\u0451\\u0442, \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0430 McNemar \\u0394=(z_{.975}+z_{.8})\\u00b7\\u221a(p_disc/N); \\u0440\\u0430\\u0441\\u0441\\u0447\\u0438\\u0442\\u0430\\u043d\\u043e \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435 \\u0430\\u0440\\u0438\\u0444\\u043c\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438, \\u0431\\u0435\\u0437 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430):\\n  \\u2022 CSQA-only, N=1221: \\u043f\\u0440\\u0438 \\u0434\\u043e\\u043b\\u0435 \\u0434\\u0438\\u0441\\u043a\\u043e\\u0440\\u0434\\u0430\\u043d\\u0442\\u043d\\u044b\\u0445 5%/10%/20% \\u2192 MDE \\u2248 1.8 / 2.5 / 3.6 \\u043f.\\u043f. (\\u03b1=0.05, power 0.8).\\n  \\u2022 \\u0410\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 \\u0438\\u0437 ~8 \\u0437\\u0430\\u0434\\u0430\\u0447 (N\\u224815\\u201320k, \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u044b \\u0441\\u043f\\u043b\\u0438\\u0442\\u043e\\u0432 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043d\\u0430 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u0438, \\u043e\\u043d\\u0438 \\u043e\\u0440\\u0438\\u0435\\u043d\\u0442\\u0438\\u0440\\u043e\\u0432\\u043e\\u0447\\u043d\\u043e: PIQA\\u22481838, WG\\u22481267, HellaSwag\\u224810042, ARC-e\\u22482288, ARC-c\\u22481172, SIQA\\u22481954, OBQA\\u2248500): MDE \\u2248 0.5\\u20131.0 \\u043f.\\u043f. \\u043f\\u0440\\u0438 \\u0442\\u043e\\u0439 \\u0436\\u0435 \\u0434\\u0438\\u0441\\u043a\\u043e\\u0440\\u0434\\u0430\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438.\\n  \\u0412\\u044b\\u0432\\u043e\\u0434 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430: \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 \\u0434\\u0430\\u0451\\u0442 \\u043f\\u0440\\u0438\\u0435\\u043c\\u043b\\u0435\\u043c\\u0443\\u044e \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u044c \\u043d\\u0430 \\u043f\\u043e\\u0440\\u043e\\u0433\\u0435 ~1 \\u043f.\\u043f.; \\u043e\\u0434\\u0438\\u043d\\u043e\\u0447\\u043d\\u0430\\u044f CSQA \\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u043d\\u0430 \\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u044b \\u22732\\u20133 \\u043f.\\u043f. \\u042d\\u0442\\u043e \\u0441\\u043b\\u0435\\u0434\\u0443\\u0435\\u0442 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0432 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0435 \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u0440\\u0435\\u0442\\u0430\\u0446\\u0438\\u0438: \\u00abno significant difference\\u00bb \\u043d\\u0430 CSQA-only \\u2260 \\u0440\\u0430\\u0432\\u0435\\u043d\\u0441\\u0442\\u0432\\u043e \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439.\\n- \\u0427\\u0438\\u0441\\u043b\\u043e\\u0432\\u0430\\u044f \\u043d\\u0435\\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c: greedy/likelihood \\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d \\u043f\\u043e \\u043f\\u043e\\u0441\\u0442\\u0440\\u043e\\u0435\\u043d\\u0438\\u044e, \\u0448\\u0443\\u043c \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043e\\u0442 nondeterministic GPU kernels/batch shape. \\u041e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430: \\u0444\\u0438\\u043a\\u0441\\u0430\\u0446\\u0438\\u044f seed \\u0432\\u0435\\u0437\\u0434\\u0435; \\u0434\\u043e\\u043f\\u0443\\u0441\\u043a |\\u0394score| \\u2264 1e-4 \\u043f\\u043e C5/C8; \\u0435\\u0441\\u043b\\u0438 accuracy-\\u0444\\u043b\\u0438\\u043f\\u044b \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0440\\u0430\\u043d\\u0430\\u043c\\u0438 > 0.2% items \\u2014 \\u0443\\u0434\\u0432\\u043e\\u0438\\u0442\\u044c \\u0440\\u0430\\u043d\\u044b \\u0438 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u044c \\u043c\\u0430\\u0436\\u043e\\u0440\\u0438\\u0442\\u0430\\u0440\\u043d\\u044b\\u0439/\\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 \\u0441\\u043a\\u043e\\u0440 \\u0441 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043f\\u043e\\u043c\\u0435\\u0442\\u043a\\u043e\\u0439.\\n\\n=== 6. Feasibility (\\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d; \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043e) ===\\n\\u041f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0451\\u043d\\u043d\\u044b\\u0435 \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u044f \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u044b: \\u0441\\u0435\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430 (DNS-fail), GPU \\u043d\\u0435\\u0442 (\\u043d\\u0435\\u0442 /dev/nvidia*, \\u0434\\u0440\\u0430\\u0439\\u0432\\u0435\\u0440\\u0430 \\u043d\\u0435\\u0442; \\u0432 metadata gpu_enabled:false), \\u0432\\u0435\\u0441\\u043e\\u0432/\\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u043d\\u0435\\u0442, torch/transformers \\u043d\\u0435 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u044b \\u2014 \\u0444\\u0430\\u043a\\u0442, \\u0430 \\u043d\\u0435 \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435.\\n\\u0414\\u043b\\u044f \\u0432\\u043d\\u0435\\u0448\\u043d\\u0435\\u0433\\u043e \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u0443\\u044e\\u0442\\u0441\\u044f: (i) HF-\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f \\u043a gated Llama-2-7B/13B (\\u0441\\u043e\\u0433\\u043b\\u0430\\u0448\\u0435\\u043d\\u0438\\u0435 Meta) \\u2014 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u0440\\u0438\\u0441\\u043a; (ii) \\u0447\\u0435\\u043a\\u043f\\u043e\\u0439\\u043d\\u0442 FuseLLM 7B (\\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c/\\u0438\\u043c\\u044f \\u2014 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043f\\u043e \\u0440\\u0435\\u043f\\u043e \\u0430\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432); (iii) \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b CS-\\u0437\\u0430\\u0434\\u0430\\u0447 (\\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0435, \\u043d\\u0435 gated); (iv) 1\\u00d7A100-80GB (fp16 13B \\u2248 26 \\u0413\\u0411 \\u0432\\u0435\\u0441\\u043e\\u0432 \\u2014 \\u0432\\u043b\\u0435\\u0437\\u0430\\u0435\\u0442), CUDA, transformers+lm-eval.\\n\\u041e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u0441\\u0442\\u043e\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 (\\u0430\\u043d\\u0430\\u043b\\u0438\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f, ~2\\u00b7P\\u00b7tokens \\u043f\\u0440\\u0438 50 TFLOP/s eff; \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f: ~4 pass/\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440 \\u00d7 ~150 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432):\\n \\u2022 CSQA-only: <0.1 GPU\\u00b7\\u0447 \\u043d\\u0430 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c. \\u0412\\u0435\\u0441\\u044c CS-\\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 (~20k \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432): \\u22481.5 GPU\\u00b7\\u0447 (7B), \\u22482.6\\u20133 GPU\\u00b7\\u0447 (13B) \\u0447\\u0438\\u0441\\u0442\\u043e\\u0433\\u043e forward; \\u0441 \\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0430\\u043c\\u0438/\\u043e\\u0442\\u043b\\u0430\\u0434\\u043a\\u043e\\u0439/\\u0434\\u0443\\u0431\\u043b\\u044f\\u043c\\u0438 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u043d\\u044b\\u0439 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 \\u2014 10\\u201325 A100\\u00b7\\u0447\\u0430\\u0441\\u043e\\u0432 \\u043d\\u0430 \\u0432\\u0441\\u0435 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f. \\u041f\\u0440\\u0430\\u0432\\u0434\\u043e\\u043f\\u043e\\u0434\\u043e\\u0431\\u0438\\u044e \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 (\\u043d\\u0435 \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0437\\u0430\\u043a\\u0430\\u0437\\u0447\\u0438\\u043a\\u0430, per Q6).\\n\\u0420\\u0438\\u0441\\u043a\\u0438: gated-\\u0432\\u0435\\u0441\\u0430 (\\u0431\\u043b\\u043e\\u043a\\u0435\\u0440 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0430); \\u043d\\u0435\\u0440\\u0435\\u043froducible \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u044b \\u0430\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432 FuseLLM (\\u043c\\u0438\\u0442\\u0438\\u0433\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0442\\u0435\\u043c, \\u0447\\u0442\\u043e \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u2014 \\u043d\\u0430\\u0448\\u0435 \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u043e\\u0435 \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435, \\u0430 \\u043d\\u0435 \\u0440\\u0435\\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0438\\u044f \\u0438\\u0445 \\u0446\\u0438\\u0444\\u0440); \\u043d\\u0435\\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0437\\u043c kernels (\\u043c\\u0438\\u0442\\u0438\\u0433\\u0430\\u0446\\u0438\\u044f C5/C8); embedding-surgery \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0434\\u0430\\u0442\\u044c non-Llama-2 vocab (\\u043c\\u0438\\u0442\\u0438\\u0433\\u0430\\u0446\\u0438\\u044f C4 \\u2014 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0434\\u043e \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432); \\u0440\\u0430\\u0441\\u0445\\u043e\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0441 \\u0446\\u0438\\u0444\\u0440\\u0430\\u043c\\u0438 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u043d\\u0435 \\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u0444\\u0435\\u0439\\u043b\\u043e\\u043c \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 (\\u0438\\u043d\\u043e\\u0435 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 CS/prompts \\u0434\\u043e\\u043f\\u0443\\u0441\\u0442\\u0438\\u043c\\u043e \\u2014 \\u0441\\u043c. \\u00a77).\\n\\n=== 7. Assumptions vs Confirmed facts; \\u0447\\u0435\\u0433\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u041d\\u0415 \\u0434\\u043e\\u043a\\u0430\\u0437\\u044b\\u0432\\u0430\\u0435\\u0442 ===\\nCONFIRMED (\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043e \\u0432 \\u0441\\u0440\\u0435\\u0434\\u0435): /workspace \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e task.json; \\u0441\\u0435\\u0442\\u0438 \\u043d\\u0435\\u0442 (DNS failure); GPU \\u043d\\u0435\\u0442; \\u0432\\u0435\\u0441\\u043e\\u0432/\\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432/ML-\\u0431\\u0438\\u0431\\u043b\\u0438\\u043e\\u0442\\u0435\\u043a \\u043d\\u0435\\u0442; python 3.14.4, 224 CPU, 2 \\u0422\\u0411 RAM; MDE-\\u0447\\u0438\\u0441\\u043b\\u0430 \\u2014 \\u0430\\u0440\\u0438\\u0444\\u043c\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0440\\u0430\\u0441\\u0447\\u0451\\u0442.\\nASSUMPTIONS (\\u043f\\u043e\\u043c\\u0435\\u0447\\u0435\\u043d\\u043e, \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0435\\u0439 \\u0441\\u0432\\u0435\\u0440\\u043a\\u0438): A1 FuseLLM checkpoint = fused 7B (student 7B/teacher 13B), base, Llama-2-vocab \\u2014 \\u0438\\u0437 \\u043d\\u0435\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 \\u043e \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435, \\u041d\\u0415 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043e \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c \\u0432 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435. A2 CS = \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0438\\u0437\\u0443\\u0435\\u043c\\u044b\\u0439 MC-\\u043d\\u0430\\u0431\\u043e\\u0440 commonsense-\\u0437\\u0430\\u0434\\u0430\\u0447; \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u043a\\u0430\\u043d\\u0434\\u0438\\u0434\\u0430\\u0442-\\u0441\\u043e\\u0441\\u0442\\u0430\\u0432: \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 (i) \\u043e\\u0434\\u0438\\u043d\\u043e\\u0447\\u043d\\u0430\\u044f CommonSenseQA \\u0438\\u043b\\u0438 (ii) \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 {CSQA?, PIQA, WinoGrande, HellaSwag, ARC-e, ARC-c, SIQA, OBQA}; \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u0447\\u0430\\u0441\\u0442\\u044c \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430 \\u0433\\u043e\\u0432\\u043e\\u0440\\u0438\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u00abzero-shot scenarios on the Common Sense (CS) benchmark\\u00bb \\u0431\\u0435\\u0437 \\u0441\\u043f\\u0438\\u0441\\u043a\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447 \\u2014 \\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0441\\u043e\\u0441\\u0442\\u0430\\u0432 \\u041d\\u0415 \\u041e\\u041f\\u0420\\u0415\\u0414\\u0415\\u041b\\u0401\\u041d, \\u043e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u0435\\u043d \\u0441\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0441\\u043e \\u0441\\u0442\\u0430\\u0442\\u044c\\u0451\\u0439/\\u0440\\u0435\\u043f\\u043e \\u0432\\u043d\\u0435 \\u0441\\u0440\\u0435\\u0434\\u044b. \\u0414\\u0438\\u0437\\u0430\\u0439\\u043d \\u043d\\u0430\\u043c\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e insensitive \\u043a \\u0441\\u043e\\u0441\\u0442\\u0430\\u0432\\u0443: \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u2014 \\u0430\\u0431\\u0441\\u0442\\u0440\\u0430\\u043a\\u0442\\u043d\\u044b\\u0439 macro-average \\u043f\\u043e \\u0432\\u0445\\u043e\\u0434\\u044f\\u0449\\u0438\\u043c \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c, MDE-\\u0432\\u0435\\u0442\\u043a\\u0438 \\u043f\\u0440\\u043e\\u0441\\u0447\\u0438\\u0442\\u0430\\u043d\\u044b \\u0434\\u043b\\u044f \\u043e\\u0431\\u043e\\u0438\\u0445 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u043e\\u0432. A3 \\u00abLlama-2\\u00bb = base-7B \\u0442\\u043e\\u0439 \\u0436\\u0435 \\u0432\\u0435\\u0442\\u043a\\u0438. A4 harness-\\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b (\\u00a73) \\u2014 \\u043d\\u0430\\u0448\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435, \\u043d\\u0435 \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 \\u043e\\u0431 \\u0430\\u0432\\u0442\\u043e\\u0440\\u0430\\u0445.\\n\\u0414\\u0438\\u0437\\u0430\\u0439\\u041d \\u041d\\u0415 \\u0434\\u043e\\u043a\\u0430\\u0437\\u044b\\u0432\\u0430\\u0435\\u0442: \\u0447\\u0442\\u043e \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0432\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u0442 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0443 \\u0430\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432 (\\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u044b/\\u0441\\u043e\\u0441\\u0442\\u0430\\u0432 \\u043c\\u043e\\u0433\\u0443\\u0442 \\u043e\\u0442\\u043b\\u0438\\u0447\\u0430\\u0442\\u044c\\u0441\\u044f); \\u043a\\u0430\\u043a\\u043e\\u0435 \\u043d\\u0430\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435/\\u0432\\u0435\\u043b\\u0438\\u0447\\u0438\\u043d\\u0443 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0430 \\u0434\\u0430\\u0441\\u0442 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d (\\u043d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0445 \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u044b\\u0445 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432 \\u043d\\u0435 \\u0437\\u0430\\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f; \\u0446\\u0438\\u0444\\u0440\\u044b FuseLLM \\u0438\\u0437 \\u00ab\\u043f\\u0430\\u043c\\u044f\\u0442\\u0438\\u00bb \\u043d\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u044e\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u043e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435); \\u0447\\u0442\\u043e superiority \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f per-task (\\u0442\\u043e\\u043b\\u044c\\u043a\\u043e macro-\\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439); \\u043f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c \\u043d\\u0430 chat-\\u0432\\u0435\\u0440\\u0441\\u0438\\u0438/\\u0434\\u0440\\u0443\\u0433\\u0438\\u0435 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u044b/\\u044f\\u0437\\u044b\\u043a\\u0438; \\u043b\\u044e\\u0431\\u044b\\u0435 conclusions \\u0